"""Greedy paragraph-aware text wrapping."""


def wrap(text, width):
    if isinstance(width, bool) or not isinstance(width, int) or width < 1:
        raise ValueError("width must be an integer >= 1")
    paragraphs, current = [], []
    for line in text.splitlines():
        if line.strip():
            current.append(line)
        elif current:
            paragraphs.append(current)
            current = []
    if current:
        paragraphs.append(current)
    out = []
    for lines in paragraphs:
        if out:
            out.append("")
        row = ""
        for word in " ".join(lines).split():
            if not row:
                row = word
            elif len(row) + 1 + len(word) <= width:
                row += " " + word
            else:
                out.append(row)
                row = word
        out.append(row)
    return "\n".join(out)
